demo.css:
#demo {
  background: var(--demo-bg);
  color: var(--demo-fg);
  font-family: var(--demo-font, system-ui, -apple-system, sans-serif);
  padding: 16px;
  box-sizing: border-box;
}

#demo * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.palette-demo {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 800px;
  margin: 0 auto;
}

.demo-header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.demo-badge {
  display: inline-block;
  align-self: flex-start;
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-radius: 4px;
  background: var(--demo-accent);
  color: #fff;
}

.demo-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--demo-fg);
}

.demo-subtitle {
  font-size: 13px;
  color: var(--demo-muted);
}

.samples-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.samples-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--demo-muted);
}

.samples-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.sample-chip {
  background: var(--demo-surface);
  border: 1px solid var(--demo-border);
  color: var(--demo-fg);
  font-size: 11px;
  padding: 4px 10px;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.sample-chip:hover {
  border-color: var(--demo-accent);
  color: var(--demo-accent);
}

.input-card {
  background: var(--demo-surface);
  border: 1px solid var(--demo-border);
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--demo-fg);
}

.input-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.atmos-textarea {
  flex: 1 1 220px;
  background: var(--demo-bg);
  color: var(--demo-fg);
  border: 1px solid var(--demo-border);
  border-radius: 6px;
  padding: 8px 10px;
  font-size: 13px;
  font-family: inherit;
  resize: vertical;
  outline: none;
  transition: border-color 0.2s ease;
}

.atmos-textarea:focus {
  border-color: var(--demo-accent);
}

.analyze-button {
  background: var(--demo-accent);
  color: #fff;
  border: none;
  border-radius: 6px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: opacity 0.2s ease, transform 0.1s ease;
  align-self: flex-start;
}

.analyze-button:hover:not(:disabled) {
  opacity: 0.9;
  transform: translateY(-1px);
}

.analyze-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.status-box {
  font-size: 12px;
  padding: 8px 12px;
  border-radius: 6px;
  background: var(--demo-surface);
  border: 1px solid var(--demo-border);
  color: var(--demo-muted);
  transition: all 0.2s ease;
}

.status-box.error {
  border-color: #e53e3e;
  color: #e53e3e;
  background: rgba(229, 62, 62, 0.08);
}

.status-box.loading {
  border-color: var(--demo-accent);
  color: var(--demo-accent);
}

.visual-stage {
  background: var(--demo-surface);
  border: 1px solid var(--demo-border);
  border-radius: 10px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  position: relative;
  overflow: hidden;
}

.celestial-sky {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  background: var(--demo-bg);
  border: 1px solid var(--demo-border);
  border-radius: 8px;
  transition: background 0.5s ease;
}

.celestial-orb-container {
  width: 36px;
  height: 36px;
  position: relative;
  overflow: hidden;
  border-radius: 50%;
  background: var(--demo-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--demo-border);
}

.celestial-orb {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: absolute;
  top: 6px;
  transition: transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
  gap: 14px;
}

.orb-icon {
  font-size: 18px;
  line-height: 1;
}

.sky-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sky-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.sky-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--demo-fg);
}

.sky-val {
  font-size: 11px;
  font-weight: 600;
  color: var(--demo-muted);
}

.sky-meter {
  height: 6px;
  background: var(--demo-surface);
  border-radius: 3px;
  overflow: hidden;
  position: relative;
  border: 1px solid var(--demo-border);
}

.sky-bar-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #f6d365 0%, #fda085 50%, #4a00e0 100%);
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.vats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

@media (max-width: 580px) {
  .vats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 360px) {
  .vats-grid {
    grid-template-columns: 1fr;
  }
}

.vat-card {
  background: var(--demo-bg);
  border: 1px solid var(--demo-border);
  border-radius: 8px;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.vat-card.active-archetype {
  border-color: var(--demo-accent);
  box-shadow: 0 0 10px rgba(0,0,0,0.15);
}

.vat-header {
  display: flex;
  align-items: center;
  gap: 6px;
