document.addEventListener('DOMContentLoaded', () => {
  const input = document.getElementById('recipe-input');
  const btn = document.getElementById('analyze-btn');
  const status = document.getElementById('demo-status');
  const chipsContainer = document.getElementById('sample-chips');

  const samples = window.TypeSafeDemo.samples || [];

  function renderChips() {
    chipsContainer.innerHTML = '';
    samples.forEach((sample, idx) => {
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = `ts-chip ${idx === 0 ? 'is-active' : ''}`;
      chip.textContent = sample.description;
      chip.addEventListener('click', () => {
        document.querySelectorAll('.ts-chip').forEach(c => c.classList.remove('is-active'));
        chip.classList.add('is-active');
        input.value = sample.state.recipe_description || '';
        runEvaluation();
      });
      chipsContainer.appendChild(chip);
    });
  }

  async function runEvaluation() {
    const text = input.value.trim();
    if (!text) return;

    btn.disabled = true;
    status.className = 'ts-status is-loading';
    status.textContent = 'Scoring heat intensity and cooling offsets...';

    try {
      const answers = await window.TypeSafeDemo.evaluate({ recipe_description: text });
      status.className = 'ts-status';
      status.textContent = 'Analysis complete.';
      updateVisuals(answers);
    } catch (err) {
      status.className = 'ts-status is-error';
      status.textContent = window.TypeSafeDemo.describeError(err);
    } finally {
      btn.disabled = false;
    }
  }

  function updateVisuals(answers) {
    const scoreAns = answers.heat_score;
    const noulAns = answers.has_cooling_offset;

    const scoreLevel = (scoreAns && typeof scoreAns.score === 'number') ? scoreAns.score : 0;
    const coolingProb = (noulAns && typeof noulAns.noul === 'number') ? noulAns.noul : 0;

    const angle = -80 + Math.min(Math.max(scoreLevel, 0), 4) * 40;
    const needleGroup = document.getElementById('gauge-needle-group');
    if (needleGroup) {
      needleGroup.style.transform = `rotate(${angle}deg)`;
    }

    const levelLabels = [
      'Mild (Level 0)',
      'Subtle Warmth (Level 1)',
      'Moderate Kick (Level 2)',
      'Fiery Spice (Level 3)',
      'Extreme Fire (Level 4)'
    ];
    const levelDescs = [
      'Zero or negligible spice intensity.',
      'Gentle warming spice offset by base aromatics.',
      'Noticeable chili kick; balanced table spice.',
      'Intense heat from fresh hot peppers or curry paste.',
      'Extreme fire! Pepperhead territory.'
    ];
    const levelColors = [
      'var(--ts-c1)',
      'var(--ts-c2)',
      'var(--ts-c3)',
      'var(--ts-c4)',
      'var(--ts-c5)'
    ];

    const heatVal = document.getElementById('heat-value');
    const heatDesc = document.getElementById('heat-desc');
    const scoreFill = document.getElementById('score-meter-fill');

    if (heatVal) heatVal.textContent = levelLabels[scoreLevel] || `Level ${scoreLevel}`;
    if (heatDesc) heatDesc.textContent = levelDescs[scoreLevel] || '';
    if (scoreFill) {
      scoreFill.style.width = `${(scoreLevel / 4) * 100}%`;
      scoreFill.style.background = levelColors[scoreLevel] || 'var(--ts-c1)';
    }

    const coolingBadge = document.getElementById('cooling-badge');
    const coolingProbText = document.getElementById('cooling-prob');
    const coolingNote = document.getElementById('cooling-note');
    const coolingOverlay = document.getElementById('cooling-overlay');

    const percent = Math.round(coolingProb * 100);
    if (coolingProbText) coolingProbText.textContent = `${percent}% probability`;

    if (coolingProb >= 0.5) {
      if (coolingBadge) {
        coolingBadge.textContent = 'Active Cooling';
        coolingBadge.style.background = 'var(--ts-success-soft)';
        coolingBadge.style.color = 'var(--ts-success)';
      }
      if (coolingNote) {
        coolingNote.textContent = 'Cooling ingredient detected (yogurt, cream, or cucumber) dampening perceived burn.';
      }
      if (coolingOverlay) {
        coolingOverlay.innerHTML = '';
        const dropletCount = 5;
        for (let i = 0; i < dropletCount; i++) {
          const drop = document.createElement('div');
          drop.className = 'cooling-droplet';
          drop.textContent = '💧';
          drop.style.left = `${12 + i * 18}%`;
          drop.style.animationDelay = `${i * 0.4}s`;
          drop.style.animationDuration = `${2 + (i % 3) * 0.3}s`;
          coolingOverlay.appendChild(drop);
        }
      }
    } else {
      if (coolingBadge) {
        coolingBadge.textContent = 'None';
        coolingBadge.style.background = 'var(--ts-soft)';
        coolingBadge.style.color = 'var(--ts-muted)';
      }
      if (coolingNote) {
        coolingNote.textContent = 'No cooling offset detected in recipe description.';
      }
      if (coolingOverlay) {
        coolingOverlay.innerHTML = '';
      }
    }
  }

  btn.addEventListener('click', runEvaluation);
  input.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      e.preventDefault();
      runEvaluation();
    }
  });

  renderChips();
  if (samples.length > 0 && samples[0].state.recipe_description) {
    input.value = samples[0].state.recipe_description;
    runEvaluation();
  }
});

