  btn.addEventListener('click', runEvaluation);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      runEvaluation();
    }
  });

  async function runEvaluation() {
    const text = input.value.trim();
    if (!text) {
      status.className = 'ts-status is-error';
      status.textContent = 'Please enter a practice sentence.';
      return;
    }

    btn.disabled = true;
    status.className = 'ts-status is-loading';
    status.innerHTML = '<span class="ts-spinner"></span> Checking grammar agreement...';

    try {
      const answers = await window.TypeSafeDemo.evaluate({ practice_text: text });
      status.className = 'ts-status';
      status.textContent = '';
      renderResults(answers);
    } catch (err) {
      status.className = 'ts-status is-error';
      status.textContent = window.TypeSafeDemo.describeError(err);
    } finally {
      btn.disabled = false;
    }
  }

  function renderResults(answers) {
    resultPanel.style.display = 'block';

    const errorNoul = answers.has_agreement_error;
    const ratingScore = answers.agreement_rating;

    const prob = (errorNoul && typeof errorNoul.noul === 'number') ? errorNoul.noul : 0;
    const scoreVal = (ratingScore && typeof ratingScore.score === 'number') ? ratingScore.score : 2;

    const angle = -90 + (prob * 180);
    needleGroup.style.transform = 'rotate(' + angle + 'deg)';
    errorProbVal.textContent = Math.round(prob * 100) + '%';

    particleArea.innerHTML = '';
    if (prob > 0.4) {
      const p1 = document.createElement('div');
      p1.className = 'pulse-ring';
      const p2 = document.createElement('div');
      p2.className = 'pulse-ring';
      particleArea.appendChild(p1);
      particleArea.appendChild(p2);
    } else {
      for (let i = 0; i < 4; i++) {
        const sp = document.createElement('div');
        sp.className = 'sparkle';
        sp.style.left = (20 + i * 20) + '%';
        sp.style.animationDelay = (i * 0.3) + 's';
        particleArea.appendChild(sp);
      }
    }

    const fillPct = Math.min(100, Math.max(0, (scoreVal / 2) * 100));
    ratingMeterFill.style.width = fillPct + '%';

    if (scoreVal < 0.7) {
      badgeStatus.textContent = 'Agreement Error';
      badgeStatus.style.background = 'var(--ts-danger)';
      badgeStatus.style.color = '#fff';
      ratingTitle.textContent = 'Severe Subject-Verb Mismatch';
      ratingDesc.textContent = 'The subject and verb do not agree in number or person. Highlight target verb for correction.';
      ratingMeterFill.style.background = 'var(--ts-danger)';
    } else if (scoreVal < 1.4) {
      badgeStatus.textContent = 'Review Needed';
      badgeStatus.style.background = 'var(--ts-c4)';
      badgeStatus.style.color = 'var(--ts-ink)';
      ratingTitle.textContent = 'Questionable Structure';
      ratingDesc.textContent = 'The agreement phrasing is ambiguous or contains subtle stylistic misalignment.';
      ratingMeterFill.style.background = 'var(--ts-c4)';
    } else {
      badgeStatus.textContent = 'Flawless';
      badgeStatus.style.background = 'var(--ts-success)';
      badgeStatus.style.color = '#fff';
      ratingTitle.textContent = 'Correct Subject-Verb Agreement';
      ratingDesc.textContent = 'Grammatical number and person match accurately across subject and predicate.';
      ratingMeterFill.style.background = 'var(--ts-success)';
    }
  }
})();
